  rec jsonb;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(payload)
  LOOP
    UPDATE public.services
       SET description = rec->>'description',
           seo_description = rec->>'seo_description',
           updated_at = now()
     WHERE slug = rec->>'slug';
  END LOOP;
END $$;